"""Isi laporan akademik; data angka dibaca dari bukti percobaan."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'docs/evidence/experiments.json').read_text(encoding='utf-8'))
BROWSER=json.loads((ROOT/'docs/evidence/browser-results.json').read_text(encoding='utf-8'))
IDENTITAS=json.loads((ROOT/'docs/IDENTITAS.json').read_text(encoding='utf-8-sig'))
sections=[]
def section(title,*blocks): sections.append((title,blocks))
def p(text): return ('p',text)
def table(headers,rows): return ('table',headers,rows)
def code(text): return ('code',text)
def pic(name,caption,width=460): return ('image',name,caption,width)
def f(x): return str(x).replace('.',',')
def metrics(r):return [[m['pid'],m['completion'],m['waiting'],m['turnaround'],m['response']] for m in r['metrics']]
def trace(r):return ' | '.join(f"{s['pid']} {s['start']}-{s['end']}" for s in r['timeline'])

section('1 Pendahuluan',
p('Belajar Sistem Operasi adalah alat peraga lokal untuk mengamati pembagian giliran CPU dan pertukaran barang melalui buffer terbatas. Program menyediakan dua materi inti: Process Scheduling melalui FCFS dan Round Robin, serta IPC & Classical Problems melalui Producer–Consumer. Pengguna dapat mengubah masukan, menjalankan percobaan, dan membaca urutan kejadian bersama penjelasan hasilnya.'),
p('Kebutuhan proyek berasal dari tugas yang meminta sebuah sistem sederhana untuk tujuan pendidikan dengan minimal dua materi Sistem Operasi. Laporan harus memuat penjelasan materi serta dokumentasi sistem dengan panjang minimal dua puluh halaman. Pemilihan dua materi ini memberikan dua bentuk pengamatan yang berbeda: scheduling menghasilkan urutan waktu yang dapat dihitung ulang, sedangkan Producer–Consumer memperlihatkan interaksi pekerja yang berbagi penyimpanan.'),
p('Masalah belajar yang ingin dibantu adalah kesulitan menghubungkan istilah dengan kejadian konkret. Angka waktu tunggu kurang bermakna jika pembaca tidak mengetahui kapan proses datang dan kapan mulai berjalan. Demikian pula, istilah semaphore lebih mudah dijelaskan setelah pengguna melihat produsen harus menunggu ketika izin slot kosong belum tersedia. Karena itu, tampilan berangkat dari contoh kecil dan menyediakan informasi rinci sebagai bagian yang dapat dibuka ketika dibutuhkan.'),
p('Sistem dibangun sebagai aplikasi Python dengan antarmuka browser. Seluruh fungsi inti aplikasi memakai pustaka standar Python serta HTML, CSS dan JavaScript tanpa framework. Pengguna tidak perlu membuat akun, menghubungkan layanan luar, atau memasang package aplikasi. Program berjalan pada localhost dan tetap dapat digunakan tanpa koneksi internet setelah folder proyek tersedia.'),
p('Hasil utama proyek adalah aplikasi dengan dua tab materi, perhitungan manual yang cocok dengan kasus uji, rekaman buffer dari thread nyata, dan bukti pengujian melalui algoritma, HTTP serta browser. Laporan ini menjelaskan pilihan model, implementasi, percobaan, perbaikan yang dilakukan, dan batas kesimpulannya. Hasil yang dilaporkan berlaku untuk pengujian yang benar-benar dijalankan; tidak semua kemungkinan input dapat dicoba satu per satu.'))

section('2 Tujuan dan ruang lingkup',
p('Tujuan pertama adalah menunjukkan bagaimana aturan pemberian giliran mengubah waktu mulai dan selesai proses. Tujuan kedua adalah menunjukkan bagaimana produsen dan konsumen dapat berbagi buffer tanpa melampaui kapasitas atau mengambil barang dari tempat kosong. Tujuan ketiga adalah mendokumentasikan rancangan, implementasi, dan pengujian sehingga hubungan antara teori dan perilaku program dapat diperiksa kembali.'),
table(['Persyaratan','Pemenuhan dalam sistem'],[['Minimal dua materi','Penjadwalan CPU dan Producer–Consumer'],['Tujuan pendidikan','Contoh kecil, Gantt chart, pemutaran log buffer'],['Penjelasan materi','Aturan, rumus, analogi, batas model'],['Dokumentasi','Arsitektur, input, screenshot dan pengujian'],['Laporan minimal 20 halaman','Jumlah halaman PDF diperiksa setelah render']]),
p('Simulator scheduling menggunakan satu CPU atau core konseptual. Setiap proses memiliki waktu datang dan satu burst CPU yang diketahui. Tidak ada operasi I/O di tengah pekerjaan, tidak ada biaya waktu context switch, dan tidak ada perubahan prioritas pada dua algoritma inti. Waktu berupa bilangan bulat dalam satuan simulasi; angka tersebut tidak dimaksudkan sebagai waktu aktual CPU laptop.'),
p('Producer–Consumer utama menggunakan satu thread produsen dan satu thread konsumen dalam satu proses Python. Barang berupa label teks, bukan file atau pesan antarprogram. Kapasitas dan jumlah barang dibatasi agar percobaan singkat. Antarmuka memutar ulang hasil setelah thread selesai; kecepatan pemutaran dipisahkan dari waktu kejadian sebenarnya.'),
p('Kode tambahan dari versi sebelumnya, termasuk algoritma scheduling lain dan modul deadlock, dipertahankan sebagai materi eksplorasi. Tautan menuju tampilan tambahan tersedia pada bagian bawah halaman. Materi tersebut tidak dipakai untuk memperluas klaim utama laporan. Dengan pembatasan ini, pembaca dapat memahami dua materi inti sebelum menjelajahi fitur yang lebih luas.'))

section('3 Proses dan model waktu',
p('Subbab 2.1 menjelaskan proses secara teori. Subbab ini menjelaskan bagaimana proses dan waktu disimpan di dalam aplikasi, sehingga pembaca dapat menghubungkan angka pada layar dengan data yang diolah program.'),
p('Pada aplikasi, proses direpresentasikan oleh objek Process. Objek ini menyimpan nama, arrival, burst, dan field prioritas untuk kompatibilitas dengan materi tambahan. FCFS dan Round Robin tidak menggunakan field prioritas. Nama dipakai untuk menghubungkan segmen pada grafik dengan baris hasil perhitungan. Karena itu, dua proses tidak boleh memiliki nama sama dalam satu percobaan.'),
table(['Istilah','Makna pada model','Contoh'],[['Nama proses','Identitas pekerjaan','P1'],['Arrival','Waktu pekerjaan siap','0'],['Burst','Kebutuhan waktu CPU','5'],['Segmen','Interval penggunaan CPU','P1 dari 0 sampai 5'],['IDLE','Tidak ada proses siap','CPU kosong 0 sampai 5']]),
p('Jam simulasi dimulai dari nol. Jika proses pertama baru datang pada waktu lima, interval nol sampai lima dicatat sebagai IDLE. Nama IDLE dikhususkan bagi keadaan ini dan ditolak sebagai nama proses pengguna. Pembatasan tersebut diperlukan karena penghitungan metrik dan pewarnaan grafik membedakan segmen proses dari segmen kosong berdasarkan penanda itu.'),
p('Interval ditulis dengan awal termasuk dan akhir tidak termasuk, misalnya [0,5). Durasi interval adalah lima satuan. Dua interval yang berbatasan pada angka yang sama tidak berarti terjadi tumpang tindih. P1 dapat selesai pada waktu lima dan P2 mulai pada waktu lima. Penjelasan ini membantu membaca batas batang Gantt tanpa menghitung titik akhir dua kali.'),
p('Tabel metrik diurutkan menurut nama proses untuk memudahkan pencarian. Urutan tabel tidak selalu sama dengan urutan eksekusi. Urutan eksekusi yang menjadi dasar perhitungan berada pada timeline. Pengguna sebaiknya membaca grafik terlebih dahulu sebelum membandingkan angka pada tabel.'))

section('4 Aturan FCFS dalam simulator',
p('First Come First Served memberi giliran kepada pekerjaan berdasarkan kedatangannya. Pekerjaan yang sudah mendapat CPU berjalan sampai selesai pada model nonpreemptive ini. Sifat sederhana tersebut memudahkan penelusuran, tetapi pekerjaan panjang yang berada di depan dapat membuat pekerjaan pendek menunggu. Pembahasan kebijakan dasar penjadwalan dan pengukuran turnaround dapat ditemukan pada OSTEP bab Scheduling Introduction [2]. Dalam kehidupan sehari-hari, FCFS mirip antrean kasir: pelanggan pertama dilayani sampai selesai walaupun pelanggan di belakangnya hanya membeli satu barang. Akibatnya, satu pekerjaan panjang di depan dapat membuat banyak pekerjaan pendek menunggu lama; gejala ini dikenal sebagai convoy effect.'),
p('Implementasi fcfs() mengurutkan daftar proses dengan kunci pasangan arrival dan pid. Waktu datang merupakan kunci utama. Nama proses menjadi pemutus urutan ketika dua waktu datang sama. Aturan tambahan ini merupakan keputusan implementasi yang harus diketahui saat membandingkan hasil dengan perhitungan manual. Nama dibandingkan sebagai teks, sehingga P10 dapat berada sebelum P2.'),
code('urutkan proses berdasarkan (arrival, nama)\njam = 0\nuntuk setiap proses:\n    jika jam < arrival: catat IDLE sampai arrival\n    mulai = maksimum(jam, arrival)\n    selesai = mulai + burst\n    catat segmen proses\n    jam = selesai'),
p('Pseudocode tersebut menjelaskan aturan program sendiri. Setiap proses menghasilkan satu segmen aktif. Jika ada jeda kedatangan, program menambahkan segmen IDLE sebelum proses berikutnya. Dengan demikian, grafik memuat waktu kosong sekaligus waktu kerja. Fungsi pembentuk metrik kemudian membaca timeline yang sama; frontend tidak menghitung ulang algoritma secara terpisah.'),
p('Dalam demo, pengguna dapat mengubah lama P1 dari lima menjadi dua puluh empat untuk melihat dampak pekerjaan panjang. Nilai waktu tunggu proses berikutnya bertambah karena mereka belum memperoleh giliran. Fenomena yang diperlihatkan bukan kesalahan FCFS, melainkan akibat dari aturan tidak memotong pekerjaan aktif. Penjelasan ini penting agar pengguna membedakan perilaku algoritma dari bug implementasi.'),
p('FCFS berguna sebagai acuan karena urutannya mudah diverifikasi dengan penjumlahan sederhana. Acuan ini dipakai pada pengujian manual sebelum membandingkannya dengan Round Robin. Aplikasi tidak menyatakan FCFS selalu buruk atau selalu terbaik; penilaian bergantung pada data dan ukuran yang ingin diperhatikan.'))

section('5 Aturan Round Robin dalam simulator',
p('Round Robin membagi CPU dalam giliran dengan batas waktu yang disebut quantum. Proses yang belum selesai setelah satu giliran dimasukkan lagi ke belakang antrean. Dalam literatur penjadwalan, pembagian waktu ini berkaitan dengan tujuan respons yang lebih cepat serta biaya pergantian pekerjaan [2]. Simulator memperlihatkan pembagian giliran, tetapi tidak menambahkan durasi biaya perpindahan pada jam model. Cara ini mirip beberapa anak yang bergantian memakai satu mainan, masing-masing dua menit: yang belum puas kembali mengantre di belakang, sehingga tidak ada yang menunggu terlalu lama untuk giliran pertamanya.'),
p('Fungsi round_robin() menyimpan sisa burst untuk setiap nama proses dan sebuah antrean siap. Lama satu giliran adalah nilai terkecil antara quantum dan sisa burst. Proses yang hanya memiliki satu satuan pekerjaan tersisa akan selesai dalam satu satuan walaupun quantum bernilai dua. Karena itu, tidak semua batang dalam Gantt chart harus memiliki lebar yang sama.'),
code('masukkan proses yang sudah datang ke antrean\nselama masih ada pekerjaan:\n    bila antrean kosong: lompat ke kedatangan berikutnya\n    ambil proses dari depan antrean\n    durasi = minimum(quantum, sisa burst)\n    jalankan dan kurangi sisa burst\n    masukkan proses yang tiba sampai akhir giliran\n    jika proses belum selesai: antrekan kembali'),
p('Kedatangan tepat di batas quantum diterima sebelum proses aktif dimasukkan ulang. Sebagai contoh, jika P1 berjalan dari nol sampai dua dan P3 datang pada dua, P3 masuk bersama proses baru sebelum P1 kembali ke belakang. Aturan ini menentukan urutan contoh manual dan dilindungi oleh kasus uji khusus. Mengubahnya tanpa memperbarui penjelasan akan membuat hasil sulit dibandingkan.'),
p('Batas setiap giliran tetap disimpan pada timeline walaupun hanya satu proses yang tersedia. Satu proses dengan burst lima dan quantum dua menghasilkan tiga giliran: dua, dua, dan satu. Namun, pergantian antarprosesnya nol karena identitas proses tidak berubah. Perbedaan antara habisnya quantum dan pergantian proses merupakan salah satu perbaikan penting proyek ini.'),
p('Pengguna dapat mencoba quantum satu, dua, tiga, lalu lima pada contoh awal. Hasil percobaan memperlihatkan bahwa respons, waktu tunggu, dan jumlah pergantian tidak harus berubah dengan pola yang sama. Kesimpulan diambil dari tabel hasil per input, bukan dari anggapan bahwa quantum terkecil selalu paling baik.'))

section('6 Membaca dan menghitung metrik',
p('Metrik menjawab pertanyaan berbeda. Waktu selesai menjelaskan kapan pekerjaan berakhir. Turnaround mencakup seluruh rentang sejak kedatangan. Waktu tunggu hanya menghitung bagian rentang tersebut ketika proses belum memakai CPU dalam model tanpa I/O. Respons berfokus pada giliran pertama, sehingga berbeda dari waktu selesai untuk proses yang terpotong beberapa kali.'),
table(['Ukuran','Rumus dalam program'],[['Completion','Akhir segmen terakhir proses'],['Turnaround','Completion dikurangi arrival'],['Waiting','Turnaround dikurangi burst'],['Response','Awal segmen pertama dikurangi arrival'],['Rata-rata','Jumlah nilai semua proses dibagi jumlah proses']]),
p('Contoh P2 pada FCFS: waktu datang satu, burst tiga, mulai lima, dan selesai delapan. Turnaround adalah tujuh. Dari tujuh satuan itu, tiga dipakai untuk bekerja sehingga empat sisanya adalah waktu tunggu. Karena hanya ada satu giliran, waktu tunggu dan respons sama-sama empat. Persamaan angka tersebut tidak berlaku umum untuk Round Robin.'),
p('Pada Round Robin quantum dua, P2 mulai pada dua dan selesai pada delapan. Responsnya satu, tetapi total waktu tunggunya empat. P2 sempat bekerja, kembali mengantre, lalu bekerja lagi. Contoh ini menunjukkan mengapa satu angka saja tidak cukup untuk menggambarkan pengalaman suatu proses. Program menampilkan tiga rata-rata utama dan menyediakan detail per proses.'),
p('Fungsi build_metrics() memperoleh waktu pertama dan terakhir dari timeline. Hasil numerik tidak berasal dari posisi visual batang atau lebar piksel. Rata-rata dibulatkan dua angka desimal untuk tampilan, sementara waktu tiap proses tetap berupa integer. Perbandingan manual menggunakan pecahan terlebih dahulu kemudian membulatkannya, sehingga tidak menumpuk kesalahan pembulatan dari langkah sebelumnya.'),
p('Context switch pada laporan didefinisikan sebagai peralihan langsung antara dua proses yang berbeda. Dispatch pertama dan peralihan ke atau dari IDLE tidak dihitung. Definisi ini dijelaskan karena istilah yang sama dapat diberi batas pengukuran berbeda. Angka tersebut bukan pengukuran context switch sistem operasi laptop, dan tidak boleh dipakai untuk menghitung overhead nyata tanpa model tambahan.'))

section('7 Thread dan masalah berbagi data',
p('Thread adalah alur eksekusi di dalam proses. Beberapa thread dalam proses yang sama dapat mengakses ruang data bersama. Hal ini memberi kesempatan bekerja secara konkuren, sekaligus menuntut koordinasi ketika beberapa thread mengakses data yang sama [3]. Pada proyek ini, data bersama tersebut adalah daftar barang dalam buffer.'),
p('Modul threading Python menyediakan Thread, Lock, Semaphore, dan Event. Thread menjalankan fungsi pekerja, Lock mengatur akses eksklusif, Semaphore mengatur izin yang dihitung, sedangkan Event digunakan untuk memberi sinyal pembatalan. Dokumentasi Python juga membedakan konkurensi thread dari kemampuan eksekusi paralel CPU pada build CPython yang menggunakan GIL [4]. Demo ini tidak digunakan sebagai benchmark peningkatan kecepatan komputasi.'),
p('Produsen menjalankan loop untuk membuat label barang, menunggu jeda produksi, kemudian meminta buffer menerima barang tersebut. Konsumen mempunyai kuota pengambilan dan jeda konsumsi. Satu item memiliki identitas seperti item-1.3, yang menyatakan barang ketiga dari produsen pertama. Label ini membuat urutan barang dapat dibandingkan antara rekaman produksi dan konsumsi.'),
table(['Bagian','Data atau tanggung jawab'],[['Produsen','Membuat label dan meminta put'],['Konsumen','Meminta get sesuai kuota'],['BoundedBuffer','Menjaga isi, kapasitas dan semaphore'],['Recorder','Menyimpan kejadian dan snapshot'],['Pengendali percobaan','Memulai, menunggu dan membatalkan pekerja']]),
p('Antarmuka utama menetapkan satu produsen dan satu konsumen agar hubungan sebab akibat mudah dilihat. Backend tetap mendukung beberapa pekerja untuk mempertahankan kemampuan tambahan dan menguji konsistensi pencatatan. Pengujian dengan banyak pekerja tidak mengubah materi utama; tujuannya membantu menemukan kesalahan yang mungkin tersembunyi pada urutan eksekusi sederhana.'),
p('Sebutan IPC & Classical Problems pada tugas dipenuhi melalui masalah klasik Producer–Consumer dan mekanisme sinkronisasinya. Implementasinya tidak membuat dua proses OS yang terpisah, tidak menggunakan pipe antarprogram, dan tidak melakukan komunikasi jaringan antarpekerja. HTTP hanya menghubungkan antarmuka browser dengan server aplikasi. Batas ini dinyatakan agar konsep demonstrasi tidak salah dijelaskan saat presentasi.'))

section('8 Semaphore mutex dan buffer terbatas',
p('Semaphore menyimpan jumlah izin yang tersedia. Operasi memperoleh izin dapat membuat pemanggil menunggu ketika izin belum tersedia. Operasi pelepasan mengembalikan izin. Pada masalah buffer terbatas, satu semaphore dapat mewakili slot kosong dan satu lagi barang yang siap diambil. Pola Producer–Consumer dengan semaphore dibahas pada OSTEP bab Semaphores [5]. Semaphore empty dapat dibayangkan sebagai papan jumlah tempat parkir kosong: produsen hanya boleh menaruh barang jika angkanya lebih dari nol. Semaphore full adalah kebalikannya, yaitu jumlah barang yang siap diambil konsumen.'),
p('Mutex mempunyai tugas berbeda: melindungi critical section agar hanya satu thread mengubah data buffer pada satu waktu. Penggunaan lock di sekitar operasi terhadap data bersama membantu membuat rangkaian perubahan tersebut terlihat sebagai satu tindakan yang utuh terhadap thread lain [6]. Dalam proyek ini, perubahan isi dan perekaman snapshot berada dalam perlindungan yang sama.'),
table(['Mekanisme','Nilai awal','Peran pada aplikasi'],[['empty','Kapasitas buffer','Izin menaruh satu barang'],['full','Nol','Izin mengambil satu barang'],['mutex','Tidak terkunci','Melindungi isi dan snapshot'],['cancel','Belum diset','Menghentikan pekerja jika gagal']]),
p('Urutan operasi produsen adalah memperoleh izin empty, masuk ke mutex, menambahkan barang dan log, keluar dari mutex, lalu melepas izin full. Konsumen memperoleh full, masuk ke mutex, mengambil barang terdepan dan mencatat log, lalu melepas empty. Thread tidak menunggu izin empty atau full sambil memegang mutex. Pemisahan urutan ini memungkinkan pasangan pekerja tetap mengubah buffer saat pekerja pertama sedang menunggu.'),
p('Aturan yang harus selalu benar pada buffer (disebut invariant) adalah jumlah barang tidak pernah kurang dari nol dan tidak pernah melebihi kapasitas. Tampilan tidak membaca angka semaphore untuk menunjukkan isi buffer, karena sebuah thread bisa saja sudah mengambil izin tetapi belum menaruh barang. Yang ditampilkan adalah salinan isi buffer (snapshot) yang diambil di dalam mutex, sehingga gambar selalu sesuai dengan isi buffer saat itu.'),
p('Keadaan menunggu tidak otomatis berarti deadlock. Produsen yang menunggu slot dapat dilanjutkan setelah konsumen mengambil barang. Sebaliknya, konsumen dapat dilanjutkan setelah produsen memasukkan barang. Pemeriksaan akhir menuntut semua barang selesai dipindahkan dan seluruh thread berhenti. Jika batas waktu terlampaui, hasil ditandai gagal dan pekerja diberi sinyal pembatalan.'))

section('9 Rancangan arsitektur aplikasi',
p('Arsitektur dipisahkan menjadi tiga bagian: antarmuka, endpoint HTTP, dan modul algoritma. Pemisahan ini menjaga perhitungan tetap berada pada satu sumber. Browser menangani masukan dan tampilan, server memvalidasi permintaan, dan modul Python menghasilkan data simulasi. Tidak ada database karena seluruh percobaan dapat dijalankan dari parameter yang dimasukkan pengguna.'),
code('Browser: HTML + CSS + JavaScript\n              | POST JSON\n              v\nServer lokal: validasi dan pemilihan modul\n              |\n       +------+----------------+\n       v                       v\nFCFS / Round Robin      Producer / Consumer\n       |                       |\nTimeline + metrik       Kejadian + snapshot\n       +-----------+-----------+\n                   v\n       JSON ke browser untuk ditampilkan'),
p('Endpoint /api/scheduling menerima daftar proses dan nama algoritma. Untuk perbandingan dua algoritma inti, antarmuka mengirim dua permintaan dengan data proses yang sama. Respons masing-masing berisi hasil tunggal. Pendekatan ini menggunakan kemampuan backend yang sudah ada tanpa memaksa halaman utama menampilkan seluruh algoritma tambahan.'),
p('Endpoint /api/ipc/producer-consumer menjalankan percobaan sampai selesai atau sampai gagal. Respons memuat parameter, jumlah produksi dan konsumsi, isi tertinggi, kejadian menunggu, status thread, dan daftar kejadian. Setelah respons diterima, browser menyediakan kontrol pemutaran. Oleh karena itu, kelambatan pemutaran visual tidak memengaruhi penjadwalan thread pada percobaan yang sudah selesai.'),
p('Server memakai ThreadingHTTPServer agar permintaan dapat ditangani oleh thread server. Thread server berbeda dari thread produsen dan konsumen yang dipakai dalam percobaan. Semua objek buffer dibuat untuk masing-masing pemanggilan run_demo(), sehingga dua percobaan tidak berbagi daftar barang yang sama. Data ekspor JSON diunduh ke pengguna melalui browser; aplikasi tidak mengirimkannya ke layanan luar.'),
p('Berkas web disajikan dari direktori web. Dokumen laporan dan bukti pengujian berada di direktori terpisah dalam proyek. Dokumen tersebut dibuka melalui pengelola berkas. Pembatasan ini menjaga aplikasi tetap kecil serta membuat lokasi kode, dokumentasi, dan hasil percobaan mudah dikenali.'))

section('10 Kontrak masukan dan validasi',
p('Input yang tidak sesuai tidak boleh diam-diam berubah menjadi nilai lain. Misalnya, burst nol bukan pekerjaan selama satu satuan, dan angka 1,5 bukan otomatis satu. Versi akhir menolak input semacam itu dengan pesan yang menyebut kolom dan batas yang diperbolehkan. Validasi dilakukan di browser untuk kenyamanan dan di server karena endpoint tetap dapat dipanggil tanpa formulir.'),
table(['Masukan','Batas inti','Penanganan'],[['Jumlah proses','1 sampai 12','Tolak kosong/berlebihan'],['Nama proses','1 sampai 12 karakter','Tolak duplikat dan IDLE'],['Waktu datang','0 sampai 100','Integer'],['Lama proses','1 sampai 50','Integer positif'],['Quantum','1 sampai 20','Integer positif'],['Kapasitas buffer','1 sampai 10','Integer positif'],['Jumlah barang','1 sampai 12','Integer positif'],['Jeda pekerja','0 sampai 100 ms','Integer pada API']]),
p('Formulir utama menyediakan tiga pilihan jeda yang diminta pekerja: sepuluh, empat puluh, dan delapan puluh milidetik. Nilai ini tidak menjamin jarak waktu antarbarang sama persis dengan parameter. Pilihan bertuliskan cepat, sedang, dan lambat membantu pengguna menghubungkan nilai jeda dengan perilaku. API mempertahankan rentang yang lebih luas untuk pengujian. Jumlah produsen dan konsumen pada halaman utama tetap satu; parameter tambahan backend dibatasi antara satu dan lima.'),
p('Server memeriksa bentuk data sebelum membaca setiap field. Daftar proses harus benar-benar berupa list yang tidak kosong, dan setiap elemennya harus berupa objek. Boolean tidak diterima sebagai angka walaupun bahasa Python memperlakukan bool sebagai turunan int. Pemeriksaan ini mencegah masukan seperti true lolos sebagai waktu satu pada API.'),
p('Pada sisi browser, kolom angka dibaca sebagai integer utuh. Masukan kosong atau pecahan menampilkan kesalahan. Tombol dan kontrol formulir dinonaktifkan selama permintaan berjalan untuk menghindari perubahan konfigurasi yang membingungkan saat hasil sedang dihitung. Setelah selesai atau gagal, kontrol dipulihkan agar pengguna dapat memperbaiki masukan dan mengulang percobaan.'),
p('Respons kesalahan input memakai status HTTP 400. Pesan ditampilkan dekat tombol pelaksanaan, bukan hanya pada console pengembang. Kondisi server tidak terhubung juga menghasilkan arahan untuk membuka aplikasi melalui launcher. Tujuannya agar pengguna awam dapat membedakan kesalahan input dari kondisi server yang belum berjalan.'))

section('11 Verifikasi manual FCFS',
p('Data contoh terdiri dari tiga proses. P1 datang pada nol dengan kebutuhan CPU lima, P2 datang pada satu dengan kebutuhan tiga, dan P3 datang pada dua dengan kebutuhan satu. Semua proses menggunakan nama unik. FCFS mempertahankan P1 sampai selesai sehingga kedatangan P2 dan P3 tidak memotong pekerjaan P1.'),
table(['Proses','Datang','Lama CPU'],[[r['pid'],r['arrival'],r['burst']] for r in DATA['sample']]),
p('P1 mulai pada nol dan selesai pada lima. Pada waktu lima, P2 sudah menunggu sejak satu dan P3 sejak dua. P2 datang lebih awal sehingga mendapat giliran kedua, berjalan sampai delapan. P3 lalu memakai CPU selama satu satuan dan selesai pada sembilan. Tidak ada interval idle karena selalu ada pekerjaan yang tersedia setelah P1 mulai.'),
code(trace(DATA['fcfs'])),
table(['Proses','Selesai','Tunggu','Turnaround','Respons'],metrics(DATA['fcfs'])),
p('Untuk P1, turnaround lima dikurangi nol menghasilkan lima, kemudian dikurangi burst lima menghasilkan waktu tunggu nol. Untuk P2, turnaround delapan dikurangi satu menghasilkan tujuh; waktu tunggu tujuh dikurangi tiga adalah empat. Untuk P3, turnaround sembilan dikurangi dua menghasilkan tujuh; waktu tunggu tujuh dikurangi satu adalah enam.'),
p('Jumlah waktu tunggu adalah sepuluh, sehingga rata-ratanya sepuluh dibagi tiga atau 3,33 setelah pembulatan. Jumlah turnaround adalah sembilan belas sehingga rata-ratanya 6,33. Karena setiap proses hanya memiliki satu giliran aktif, respons sama dengan waktu tunggu pada contoh ini. Pergantian terjadi dari P1 ke P2, lalu P2 ke P3, sehingga jumlahnya dua.'),
p('Nilai manual ini dijadikan expected result pada test_core.py. Pemeriksaan membandingkan seluruh urutan segmen dan metrik tiap proses, bukan hanya memeriksa bahwa respons API memiliki field. Dengan demikian, perubahan implementasi yang tetap menghasilkan JSON tetapi mengubah urutan atau angka akan terdeteksi pada contoh ini.'))

section('12 Verifikasi manual Round Robin',
p('Contoh yang sama dijalankan dengan quantum dua. P1 memperoleh giliran pertama dari nol sampai dua dan masih mempunyai tiga satuan pekerjaan. Pada waktu dua, P2 dan P3 sudah datang. Keduanya masuk antrean sebelum P1 dikembalikan ke belakang. Antrean berikutnya adalah P2, P3, P1.'),
table(['Giliran','Proses','Interval','Sisa setelah giliran'],[[1,'P1','0–2',3],[2,'P2','2–4',1],[3,'P3','4–5',0],[4,'P1','5–7',1],[5,'P2','7–8',0],[6,'P1','8–9',0]]),
p('P2 memakai dua satuan pada giliran kedua dan tersisa satu. P3 hanya memerlukan satu satuan sehingga selesai pada waktu lima. P1 kemudian menggunakan dua satuan lagi, diikuti P2 yang menyelesaikan satu satuan terakhir. Terakhir, P1 menyelesaikan sisa pekerjaannya pada waktu sembilan.'),
table(['Proses','Selesai','Tunggu','Turnaround','Respons'],metrics(DATA['round_robin']['2'])),
p('P1 selesai pada sembilan, sehingga turnaround sembilan dan waktu tunggu empat. P2 tetap selesai pada delapan dengan turnaround tujuh dan waktu tunggu empat. P3 selesai lebih cepat, pada lima, dengan turnaround tiga dan waktu tunggu dua. Total waktu tunggu masih sepuluh, sama dengan FCFS pada data ini, walaupun pembagiannya berubah.'),
p('Waktu pertama berjalan adalah nol untuk P1, dua untuk P2, dan empat untuk P3. Setelah dikurangi waktu datang masing-masing, responsnya nol, satu, dan dua. Rata-ratanya satu, lebih kecil daripada respons FCFS 3,33 pada contoh yang sama. Ada enam segmen aktif dengan pergantian identitas pada setiap batas, sehingga lima pergantian antarproses dihitung.'),
p('Kasus ini juga memverifikasi kedatangan tepat pada batas quantum: P3 datang pada waktu dua. Tes mengharuskan urutan tersebut tetap sesuai aturan yang didokumentasikan. Perbandingan ini memberi alasan konkret mengapa respons dapat membaik tanpa perubahan rata-rata waktu tunggu pada dataset tertentu.'))

section('13 Percobaan pengaruh quantum',
p('Percobaan mengubah quantum dengan data P1, P2 dan P3 yang sama. Nilai quantum yang digunakan adalah satu, dua, tiga, lima, sepuluh dan dua puluh. Semua hasil berikut berasal dari scripts/collect_evidence.py dan tersimpan pada docs/evidence/experiments.json. Setiap perubahan parameter dilakukan pada fungsi yang sama dengan fungsi yang dipanggil endpoint aplikasi.'),
table(['Quantum','Tunggu','Turnaround','Respons','Pergantian'],[[q,f(r['summary']['avg_waiting']),f(r['summary']['avg_turnaround']),f(r['summary']['avg_response']),r['summary']['context_switches']] for q,r in DATA['round_robin'].items()]),
p('Pada quantum satu, rata-rata respons adalah 0,33 dan terdapat tujuh pergantian antarproses. Quantum dua menghasilkan respons satu dengan lima pergantian. Quantum tiga memberi respons dua dengan tiga pergantian. Untuk quantum lima atau lebih besar, setiap burst contoh dapat selesai pada giliran pertama sehingga urutan dan metriknya sama dengan FCFS.'),
p('Rata-rata waktu tunggu pada quantum satu adalah 2,67, sedangkan pada quantum dua dan tiga nilainya 3,33. Angka tersebut merupakan hasil dari susunan kedatangan dan panjang pekerjaan tertentu. Nilai ini tidak membuktikan bahwa quantum satu akan selalu meminimalkan waktu tunggu pada dataset lain. Pengguna dapat mengganti input untuk menguji apakah pola yang sama masih terjadi.'),
p('Total waktu simulasi tetap sembilan untuk seluruh percobaan karena jumlah burst sembilan, tidak ada idle, dan model tidak menambahkan overhead. Karena itu, tabel tidak dapat digunakan untuk menyimpulkan quantum kecil tidak memiliki biaya di sistem nyata. Peningkatan jumlah pergantian menunjukkan perubahan frekuensi peralihan, sedangkan durasi biaya peralihan berada di luar cakupan model.'),
p('Perbandingan harus menyatakan ukuran dan dataset secara bersamaan. Pada tiga proses contoh, quantum dua memperbaiki rata-rata respons dibanding FCFS, sementara rata-rata waktu tunggu sama. Hasil ini menunjukkan bahwa perubahan respons tidak selalu diikuti perubahan rata-rata tunggu. Kesimpulan tetap dibatasi pada parameter percobaan yang dicatat.'))

section('14 Pekerjaan panjang dan waktu CPU kosong',
p('Dua kasus tambahan membantu memeriksa batas perilaku model. Kasus pertama menempatkan pekerjaan panjang di depan dua pekerjaan pendek yang datang bersamaan. P1 memerlukan dua puluh empat satuan, sedangkan P2 dan P3 masing-masing memerlukan tiga. Karena waktu datang sama, nama proses menentukan urutan awal.'),
table(['Algoritma','Rata-rata tunggu','Rata-rata respons','Pergantian'],[[name,f(r['summary']['avg_waiting']),f(r['summary']['avg_response']),r['summary']['context_switches']] for name,r in DATA['convoy'].items()]),
p('Pada FCFS, P2 menunggu dua puluh empat dan P3 menunggu dua puluh tujuh satuan. Rata-rata waktu tunggu menjadi tujuh belas. Angka tersebut dapat diperoleh tanpa membaca kode: cukup jumlahkan lama pekerjaan yang berada di depan masing-masing proses. Pada RR quantum dua, kedua proses pendek dapat memperoleh CPU sebelum pekerjaan panjang selesai. Hasil tabel menunjukkan perubahan pengalaman menunggu dan memperoleh giliran pertama pada konfigurasi tersebut.'),
p('Kasus kedua hanya memiliki P1 yang baru datang pada waktu lima dan membutuhkan tiga satuan CPU. Program mencatat IDLE dari nol sampai lima, kemudian P1 dari lima sampai delapan. Waktu tunggu dan respons P1 nol karena tidak ada proses lain yang mendahuluinya ketika sudah datang. Turnaround P1 adalah tiga, bukan delapan.'),
table(['Ukuran kasus idle','Nilai'],[['Waktu total',DATA['idle']['summary']['total_time']],['Waktu CPU aktif',3],['Utilisasi model',f(DATA['idle']['summary']['cpu_utilization'])+'%'],['Rata-rata tunggu',0],['Pergantian antarproses',0]]),
p('Perbedaan antara total waktu dan turnaround penting untuk mencegah salah tafsir. Total waktu diukur sejak awal sumbu simulasi nol, sedangkan turnaround diukur sejak kedatangan suatu proses. Utilisasi model pada contoh ini adalah tiga dibagi delapan, atau 37,5 persen. Ini sekadar rasio waktu aktif terhadap rentang model, bukan pengukuran Task Manager.'),
p('Pengujian juga mencakup jeda di antara dua proses. Peralihan dari proses ke IDLE lalu ke proses berikutnya tidak masuk hitungan pergantian langsung antarproses sesuai definisi laporan. Dengan mencatat aturan tersebut, hasil idle dan hasil tanpa idle tetap dapat dibandingkan secara konsisten.'))

section('15 Implementasi Producer Consumer',
p('BoundedBuffer menyimpan daftar items, kapasitas, dua semaphore dan mutex. Fungsi put() dan get() menjadi satu-satunya jalur perubahan daftar barang. Produsen tidak menambahkan barang secara langsung ke daftar, dan konsumen tidak mengambil barang tanpa memperoleh izin. Struktur ini memusatkan aturan buffer sehingga tidak tersebar di masing-masing pekerja.'),
code('put(barang):\n    peroleh izin empty tanpa memegang mutex\n    dengan mutex:\n        tambahkan barang\n        naikkan jumlah produksi\n        catat kejadian dan salin isi buffer\n    lepaskan satu izin full\n\nget():\n    peroleh izin full tanpa memegang mutex\n    dengan mutex:\n        ambil barang terdepan\n        naikkan jumlah konsumsi\n        catat kejadian dan salin isi buffer\n    lepaskan satu izin empty'),
p('Metode _acquire() pertama mencoba memperoleh semaphore tanpa menunggu. Jika belum tersedia, kejadian BLOKIR dicatat, kemudian thread mencoba memperoleh izin dengan timeout singkat sambil memeriksa sinyal cancel. Setelah berhasil, kejadian LANJUT dicatat. Cara ini mempertahankan perilaku menunggu pada semaphore, sekaligus memungkinkan pembatalan kooperatif ketika percobaan harus dihentikan.'),
p('Pengendali run_demo() menghitung total target produksi dan membagi kuota konsumsi. Pembagian kuota juga bekerja ketika jumlah konsumen lebih besar daripada barang: sebagian konsumen memperoleh kuota nol dan langsung selesai. Dengan jumlah barang yang diketahui, tidak ada konsumen yang sengaja menunggu barang tambahan setelah seluruh target selesai.'),
p('Seluruh thread diberi satu batas waktu bersama, bukan masing-masing batas penuh yang akan menumpuk. Bila ada pekerja gagal, wrapper mencatat pesan kesalahan dan menyetel cancel. Jeda pekerja menggunakan Event.wait(), sehingga dapat dibangunkan saat pembatalan. Tes menyuntikkan kegagalan pada produsen untuk memeriksa bahwa konsumen tidak tertinggal menunggu tanpa akhir.'),
p('Respons completed hanya bernilai benar jika tidak ada error, tidak ada thread yang masih aktif, dan produksi serta konsumsi sama dengan target. Antarmuka tidak menampilkan pesan berhasil hanya karena HTTP mengembalikan objek JSON. Pemisahan status transport dan status pekerjaan ini mencegah hasil parsial disalahartikan sebagai percobaan sukses.'))

section('16 Percobaan produsen lebih cepat',
p('Konfigurasi percobaan ini menggunakan kapasitas lima, delapan barang, satu produsen dan satu konsumen. Jeda produsen sepuluh milidetik dan jeda konsumen delapan puluh milidetik. Setiap skenario dijalankan lima kali. Data pada tabel adalah hasil run_demo() yang benar-benar dijalankan, bukan contoh angka yang diketik untuk menggambarkan perilaku.'),
table(['Ulangan','Dibuat','Diambil','Isi puncak','Tunggu prod.','Tunggu kons.'],[[i+1,r['produced'],r['consumed'],r['peak_buffer_usage'],r['blocked_producers'],r['blocked_consumers']] for i,r in enumerate(DATA['producer_consumer']['produsen_cepat']['runs'])]),
p('Produsen mampu mencoba memasukkan barang lebih sering daripada konsumen mengambilnya. Isi buffer kemudian bertambah sampai kapasitasnya tercapai. Setelah tidak memperoleh izin empty, produsen menunggu. Konsumen yang mengambil barang melepaskan izin empty sehingga produsen dapat melanjutkan. Pada semua ulangan yang dicatat, isi tertinggi mencapai lima dan tidak melampaui kapasitas.'),
p('Semua ulangan berakhir dengan delapan barang diproduksi dan delapan barang dikonsumsi. Sisa buffer nol dan daftar thread yang belum selesai kosong. Hasil tersebut menunjukkan bahwa jeda menunggu tidak menghilangkan barang. Produsen tetap menyelesaikan targetnya setelah tersedia kesempatan untuk menaruh barang berikutnya.'),
p('Jumlah kejadian menunggu adalah hitungan upaya memperoleh izin yang sempat gagal, bukan durasi total menunggu. Satu kejadian BLOKIR dapat diikuti interval waktu yang panjang atau pendek. Karena itu, angka dua kejadian menunggu tidak boleh dibaca sebagai dua milidetik.'),
p('Screenshot pada subbab 4.3 diambil dari percobaan lain, sehingga jumlah menunggunya bisa berbeda dari tabel ini. Hal ini wajar karena thread dijalankan oleh komputer secara nyata; angka tabel tetap memakai data percobaan yang disimpan.'),
p('Demo ini cocok untuk menjelaskan fungsi pembatasan kapasitas. Tanpa izin slot, menambah barang terus-menerus akan bertentangan dengan model buffer terbatas. Sistem memilih menunda produsen sampai terdapat ruang, sehingga kapasitas tetap dipatuhi selama proses produksi dan konsumsi.'))

section('17 Percobaan konsumen lebih cepat',
p('Pada skenario kedua, jeda produsen diubah menjadi delapan puluh milidetik dan jeda konsumen menjadi sepuluh milidetik. Parameter lain tetap sama. Perubahan satu pasangan jeda ini menjaga perbandingan tetap mudah dipahami: jumlah barang dan kapasitas tidak berubah, tetapi pekerja yang lebih sering siap melakukan tindakan berganti.'),
table(['Ulangan','Dibuat','Diambil','Isi puncak','Tunggu prod.','Tunggu kons.'],[[i+1,r['produced'],r['consumed'],r['peak_buffer_usage'],r['blocked_producers'],r['blocked_consumers']] for i,r in enumerate(DATA['producer_consumer']['konsumen_cepat']['runs'])]),
p('Konsumen mencoba mengambil barang sebelum produsen sempat menyediakan barang berikutnya. Karena full belum memberi izin, konsumen menunggu. Setelah produsen memasukkan satu barang, izin full dilepas dan konsumen dapat melanjutkan. Pada ulangan yang tercatat, puncak isi buffer satu karena barang segera diambil sebelum sempat terjadi penumpukan yang lebih besar.'),
p('Walaupun konsumen lebih cepat, jumlah konsumsi tidak boleh melampaui jumlah barang yang diproduksi. Konsumen tidak membuat barang baru dan tidak mengambil nilai dari daftar kosong. Sifat tersebut diperiksa melalui urutan label barang: label yang diambil harus sama dengan label pertama dalam antrean hasil produksi pada saat itu.'),
p('Semua percobaan selesai dengan target delapan barang. Hasil ini menunjukkan perbedaan antara kemampuan mencoba lebih sering dan keberadaan barang yang dapat diambil. Kecepatan konsumen saja tidak cukup untuk meningkatkan jumlah hasil akhir ketika produsen masih menyediakan barang secara bertahap. Pengguna dapat melihat alasan menunggu langsung pada pesan kejadian di pemutaran ulang.'),
p('Kondisi konsumen menunggu tidak diberi warna kegagalan pada aplikasi karena merupakan bagian normal dari mekanisme sinkronisasi. Pesan gagal hanya digunakan untuk input tidak valid, server yang tidak terhubung, atau percobaan yang tidak selesai. Pemilihan bahasa antarmuka ini membantu menghindari pemahaman bahwa semua bentuk blocking merupakan kesalahan.'),
p('Perbandingan kedua skenario memperlihatkan pembagian tanggung jawab semaphore: empty berkaitan dengan kesempatan produsen menaruh barang, sedangkan full berkaitan dengan kesempatan konsumen mengambil barang. Mutex tetap dibutuhkan pada kedua skenario karena melindungi perubahan daftar dan snapshot terlepas dari pihak mana yang sedang lebih cepat.'))

section('18 Percobaan jeda sama dan variasi thread',
p('Skenario ketiga memberikan jeda empat puluh milidetik kepada kedua pekerja. Secara parameter, produsen dan konsumen mempunyai jeda yang sama. Namun, kesamaan jeda tidak memaksa keduanya dieksekusi dalam urutan yang persis sama pada setiap percobaan. Awal thread, waktu bangun, perolehan lock, dan penjadwalan oleh lingkungan eksekusi masih dapat berbeda.'),
table(['Ulangan','Dibuat','Diambil','Isi puncak','Tunggu prod.','Tunggu kons.'],[[i+1,r['produced'],r['consumed'],r['peak_buffer_usage'],r['blocked_producers'],r['blocked_consumers']] for i,r in enumerate(DATA['producer_consumer']['seimbang']['runs'])]),
p('Tabel menunjukkan jumlah barang akhir selalu sama, sedangkan jumlah kejadian konsumen menunggu berubah-ubah antara dua dan enam. Perbedaan ini terjadi karena sistem operasi bebas menentukan kapan masing-masing thread dijalankan, sehingga urutan selang-seling kerja produsen dan konsumen (disebut interleaving) dapat berbeda setiap kali. Karena itu, pengujian memeriksa hal yang wajib selalu benar, yaitu kapasitas, label barang, urutan FIFO, dan semua thread selesai, bukan waktu persis setiap kejadian.'),
p('Di sinilah perbedaan kedua modul terlihat. Modul scheduling adalah perhitungan, sehingga data yang sama selalu menghasilkan Gantt chart yang sama. Modul Producer–Consumer menjalankan thread sungguhan, sehingga urutan detailnya dapat berubah. Perilaku ini sengaja dipertahankan karena memang itulah sifat program yang memakai thread.'),
p('Seluruh lima belas percobaan buffer yang dicatat berhasil memindahkan delapan barang, berakhir dengan buffer kosong, dan tidak menyisakan thread yang masih berjalan. Jika percobaan diulang di laptop lain, jumlah menunggu dan waktunya boleh berbeda, tetapi aturan buffer di atas harus tetap terpenuhi. Angka pada scheduling berupa satuan waktu simulasi, sedangkan waktu pada buffer berupa milidetik nyata, sehingga keduanya tidak dibandingkan secara langsung.'))

section('19 Keandalan pencatatan kejadian',
p('Visualisasi hanya berguna jika rekamannya menggambarkan keadaan secara konsisten. Pada versi awal, perubahan buffer dan pencatatan kejadian dilakukan dalam bagian terpisah. Di antara kedua bagian tersebut, thread lain dapat mengubah buffer atau menulis kejadian lebih dahulu. Walaupun operasi buffer terlindungi, urutan log berisiko tidak sesuai dengan urutan perubahan yang ingin dijelaskan.'),
p('Perbaikan menempatkan perubahan barang, pembaruan jumlah, dan pembuatan snapshot di dalam mutex yang sama. Recorder tetap memiliki lock internal untuk melindungi daftar kejadian. Snapshot disalin menjadi list baru, sehingga perubahan buffer berikutnya tidak mengubah isi kejadian yang sudah direkam. Setiap kejadian memuat pelaku, tindakan, detail, ukuran, kapasitas, daftar barang dan timestamp.'),
table(['Field kejadian','Kegunaan dalam pemeriksaan'],[['actor dan action','Menjelaskan pelaku serta tindakan'],['detail','Menunjukkan label barang atau alasan menunggu'],['buffer_size','Memeriksa batas kapasitas'],['items','Merekonstruksi isi buffer dan urutan FIFO'],['t','Menunjukkan waktu pencatatan sejak awal run']]),
p('Pengujian test_core.py tidak berhenti pada pemeriksaan ukuran paling besar. Tes merekonstruksi antrean dari seluruh aksi PRODUKSI dan KONSUMSI. Pada produksi, label baru ditambahkan; pada konsumsi, label harus sama dengan barang terdepan. Setelah setiap kejadian, antrean hasil rekonstruksi dibandingkan dengan snapshot items yang direkam. Dengan demikian, kesalahan urutan log dapat terdeteksi walaupun jumlah akhir barang tetap benar.'),
p('Kejadian BLOKIR mempunyai batas penafsiran khusus. Upaya memperoleh semaphore terjadi sebelum snapshot menunggu dicatat. Thread lain dapat mengubah keadaan di antara keduanya. Karena itu, pesan mengatakan izin belum tersedia saat dicoba, bukan menjamin snapshot masih menunjukkan buffer tepat penuh atau kosong. Keterangan ini juga ditampilkan dalam bagian penjelasan tambahan antarmuka.'),
p('Pemutaran browser memakai urutan array kejadian dan snapshot asli. Browser tidak menebak isi buffer dari panjang bar animasi, tidak menyusun ulang kejadian berdasarkan timestamp yang dibulatkan, dan tidak mengubah jumlah barang saat pengguna menekan Jeda. Dengan mempertahankan data sumber, tampilan dapat dipakai untuk menjelaskan hasil yang sama dengan berkas JSON ekspor.'))

section('20 Dokumentasi tampilan scheduling',
p('Halaman scheduling memisahkan pengaturan di sebelah kiri dan hasil di sebelah kanan pada layar desktop. Pengguna memilih FCFS, Round Robin, atau perbandingan keduanya. Quantum hanya ditampilkan ketika relevan. Kolom prioritas tidak ditampilkan pada halaman utama karena tidak dipakai oleh dua algoritma inti. Tiga proses contoh sudah tersedia, tetapi perhitungan baru berjalan setelah pengguna menekan tombol.'),
pic('detail-fcfs.png','Gambar 4.1 Hasil FCFS pada contoh tiga proses yang dijalankan di browser',450),
p('Hasil menempatkan Gantt chart sebelum angka, sehingga pengguna melihat urutan pekerjaan terlebih dahulu. Rata-rata menunggu, turnaround, dan respons kemudian ditampilkan sebagai tiga ukuran utama. Tabel di bawahnya memungkinkan pengguna memeriksa angka setiap proses. Detail perhitungan dan log keputusan disimpan di bagian yang dapat dibuka tanpa memenuhi layar awal dengan seluruh penjelasan.'),
p('Saat grafik panjang, area grafik dapat digeser mendatar tanpa menyebabkan seluruh halaman melebar. Warna proses konsisten di dalam hasil dan label nama tetap tersedia. Penjelasan angka disajikan dalam bahasa Indonesia. Tombol simpan hasil JSON menyediakan data yang dapat digunakan untuk dokumentasi atau pemeriksaan ulang. Screenshot ini berasal dari aplikasi yang berjalan, bukan rancangan tampilan sebelum implementasi.'))

section('21 Dokumentasi tampilan Producer Consumer',
p('Halaman Producer–Consumer menampilkan kontrol kapasitas, jumlah barang, dan kecepatan dua pekerja. Tombol preset produsen lebih cepat dan konsumen lebih cepat memudahkan penggantian skenario. Setelah percobaan selesai, hasil menampilkan tempat penyimpanan berbentuk kotak dan tombol Sebelumnya, Putar ulang, serta Berikutnya. Slider dapat dipakai untuk langsung memilih posisi rekaman.'),
pic('detail-buffer.png','Gambar 4.2 Pemutaran rekaman buffer dari percobaan thread nyata',450),
p('Kotak berwarna memuat label barang, sementara tempat kosong diberi teks kosong. Bagian kejadian menjelaskan siapa melakukan apa, nomor langkah, dan timestamp asli. Pemutaran otomatis berpindah setiap 0,6 detik agar kejadian dapat diikuti. Antarmuka menyatakan bahwa ini pemutaran ulang setelah percobaan selesai sehingga pengguna tidak menyamakan animasi dengan streaming eksekusi thread.'),
p('Ringkasan hasil akhir ditempatkan terpisah dari keadaan buffer pada langkah terpilih. Dengan demikian, angka delapan barang selesai tidak dimaksudkan sebagai jumlah barang di dalam buffer saat slider berada di tengah rekaman. Informasi menunggu dan jumlah thread belum selesai membantu menilai akhir percobaan. Pada ponsel, pengaturan dan hasil ditumpuk secara vertikal, sedangkan kotak buffer tetap berada dalam lebar layar.'))

section('22 Strategi dan hasil pengujian',
p('Pengujian dilakukan pada beberapa lapisan karena keberhasilan satu lapisan tidak membuktikan keberhasilan lapisan lain. Fungsi dapat menghasilkan angka benar tetapi frontend gagal menampilkan respons. Sebaliknya, tampilan dapat terlihat rapi walaupun rumusnya salah. Oleh karena itu, pengujian manual, fungsi, HTTP dan browser digunakan untuk menjawab pertanyaan yang berbeda.'),
table(['Lapisan','Jumlah yang dicatat','Hasil'],[['HTTP dan modul tambahan','59 pemeriksaan pada test_api.py','Lulus'],['Scheduling lama','20 pemeriksaan pada test_scheduling.py','Lulus'],['Regresi inti','21 kasus unittest pada test_core.py','Lulus'],['Browser',str(BROWSER['passed'])+' alur pemeriksaan','Lulus'],['Percobaan buffer laporan','15 run pada tiga skenario','Selesai; aturan buffer terpenuhi']]),
p('Satu kasus unittest dapat berisi beberapa pemeriksaan kecil, sehingga angka pada setiap baris tidak dijumlahkan menjadi satu total. Catatan asli setiap pengujian disimpan pada folder docs/evidence.'),
p('Tes scheduling membandingkan timeline dan metrik terhadap hasil manual, memeriksa kedatangan tepat pada batas quantum, quantum besar yang menyamai FCFS, kasus idle, nama ganda, nama IDLE, dan quantum tidak valid. Tes buffer memeriksa dua perbedaan kecepatan, banyak pekerja, konsumen lebih banyak daripada barang, serta kegagalan dan timeout. Jalur pembatalan diuji agar tidak hanya jalur sukses yang mendapat perhatian.'),
p('Pengujian browser dijalankan otomatis dengan Chrome tanpa jendela (headless) pada ukuran layar laptop 1440 × 1080 dan ponsel 390 × 844. Alur yang diperiksa mencakup FCFS, Round Robin, perbandingan, input salah, tambah dan hapus proses, simpan hasil JSON, pemutaran rekaman, tombol kecepatan, materi tambahan, dan tampilan yang tidak melebar keluar layar. Tidak ada error JavaScript yang muncul selama pengujian.'),
p('Pengujian dilakukan pada Windows dan Chrome. Browser dan sistem operasi lain belum dicoba. Proyek ini juga tidak mengukur apakah mahasiswa menjadi lebih paham setelah memakai aplikasi; hasil pengujian hanya menunjukkan bahwa aplikasi berjalan sesuai rancangan.'))

